  1	// Personal Cyrus API keys (r39). A key is "cyk_" + 8-char public prefix + "_" + 40 random base62 characters.
  2	// Only sha256(key) is stored; the plain key is returned once, at creation. Scopes are a subset of the API v1 scopes
  3	// that a customer may hold (never admin). Store behind an interface so tests and a standalone Cyrus can swap it.
  4	import { createHash, randomBytes, timingSafeEqual } from "node:crypto";
  5	import { SCOPES, type Scope } from "../api/v1/scopes";
  6	
  7	/** What a personal key may carry: everything in v1 except staff scopes. */
  8	export const PERSONAL_SCOPES = SCOPES.filter((s) => s !== "admin:read") as Exclude<Scope, "admin:read">[];
  9	export type PersonalScope = (typeof PERSONAL_SCOPES)[number];
 10	export const SCOPE_LABEL: Record<PersonalScope, string> = {
 11	  "projects:read": "Read projects", "projects:write": "Change projects", "builds:read": "Read builds", "builds:write": "Start builds (spends tokens)",
 12	  "installs:read": "Read installs", "installs:write": "Install to servers", "catalog:read": "Read the catalog", "config:write": "Change mod config",
 13	  "library:write": "Contribute to the library", "mods:read": "Read mod pages", "account:read": "Read account and tokens", "webhooks:manage": "Manage webhooks",
 14	};
 15	export const MAX_ACTIVE_KEYS = 10;
 16	export const KEY_NAME_MAX = 48;
 17	const KEY_RE = /^cyk_([A-Za-z0-9]{8})_([A-Za-z0-9]{40})$/;
 18	
 19	export type ApiKeyRow = { id: string; userId: string; name: string; prefix: string; sha256: string; scopes: string[]; createdAt: Date; lastUsedAt: Date | null; expiresAt: Date | null; revokedAt: Date | null };
 20	export type ApiKeyView = { id: string; name: string; prefix: string; scopes: PersonalScope[]; createdAt: string; lastUsedAt: string | null; expiresAt: string | null; revokedAt: string | null; active: boolean };
 21	
 22	export interface ApiKeyStore {
 23	  listForUser(userId: string): Promise<ApiKeyRow[]>;
 24	  insert(row: Omit<ApiKeyRow, "id" | "createdAt" | "lastUsedAt" | "revokedAt">): Promise<ApiKeyRow>;
 25	  /** Revoke only if the key belongs to userId; returns false otherwise (never reveals another user's key). */
 26	  revoke(userId: string, id: string, at: Date): Promise<boolean>;
 27	  bySha(sha256: string): Promise<ApiKeyRow | null>;
 28	  touch(id: string, at: Date): Promise<void>;
 29	}
 30	
 31	const B62 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
 32	function base62(n: number): string {
 33	  let out = "";
 34	  while (out.length < n) { for (const b of randomBytes(n * 2)) { if (b < 248 && out.length < n) out += B62[b % 62]; } }
 35	  return out;
 36	}
 37	export const sha256Hex = (s: string) => createHash("sha256").update(s, "utf8").digest("hex");
 38	
 39	export function newKeyMaterial(): { key: string; prefix: string; sha256: string } {
 40	  const prefix = base62(8), secret = base62(40), key = `cyk_${prefix}_${secret}`;
 41	  return { key, prefix, sha256: sha256Hex(key) };
 42	}
 43	
 44	export function parseScopes(raw: unknown): { ok: true; scopes: PersonalScope[] } | { ok: false; error: string } {
 45	  const arr = Array.isArray(raw) ? raw : typeof raw === "string" ? [raw] : [];
 46	  const out = [...new Set(arr.map(String))];
 47	  if (!out.length) return { ok: false, error: "Pick at least one permission." };
 48	  const bad = out.find((s) => !(PERSONAL_SCOPES as readonly string[]).includes(s));
 49	  if (bad) return { ok: false, error: `Unknown permission: ${bad.slice(0, 40)}` };
 50	  return { ok: true, scopes: PERSONAL_SCOPES.filter((s) => out.includes(s)) };
 51	}
 52	
 53	export function parseKeyName(raw: unknown): { ok: true; name: string } | { ok: false; error: string } {
 54	  const n = String(raw ?? "").replace(/[\u0000-\u001f\u007f]/g, "").trim();
 55	  if (!n) return { ok: false, error: "Give the key a name." };
 56	  if (n.length > KEY_NAME_MAX) return { ok: false, error: `Keep the name under ${KEY_NAME_MAX} characters.` };
 57	  return { ok: true, name: n };
 58	}
 59	
 60	const EXPIRY_DAYS = [0, 30, 90, 365] as const;
 61	export function parseExpiry(raw: unknown, now: Date): { ok: true; at: Date | null } | { ok: false; error: string } {
 62	  const d = Number(raw ?? 90);
 63	  if (!(EXPIRY_DAYS as readonly number[]).includes(d)) return { ok: false, error: "Pick an expiry." };
 64	  return { ok: true, at: d === 0 ? null : new Date(now.getTime() + d * 86_400_000) };
 65	}
 66	
 67	export const isActive = (r: Pick<ApiKeyRow, "revokedAt" | "expiresAt">, now: Date) => !r.revokedAt && (!r.expiresAt || r.expiresAt > now);
 68	
 69	export function toView(r: ApiKeyRow, now: Date): ApiKeyView {
 70	  return {
 71	    id: r.id, name: r.name, prefix: r.prefix, scopes: r.scopes.filter((s): s is PersonalScope => (PERSONAL_SCOPES as readonly string[]).includes(s)),
 72	    createdAt: r.createdAt.toISOString(), lastUsedAt: r.lastUsedAt?.toISOString() ?? null, expiresAt: r.expiresAt?.toISOString() ?? null,
 73	    revokedAt: r.revokedAt?.toISOString() ?? null, active: isActive(r, now),
 74	  };
 75	}
 76	
 77	export async function createKey(store: ApiKeyStore, userId: string, input: { name: unknown; scopes: unknown; expiryDays?: unknown }, now = new Date()):
 78	  Promise<{ ok: true; key: string; view: ApiKeyView } | { ok: false; error: string }> {
 79	  const name = parseKeyName(input.name); if (!name.ok) return name;
 80	  const scopes = parseScopes(input.scopes); if (!scopes.ok) return scopes;
 81	  const exp = parseExpiry(input.expiryDays, now); if (!exp.ok) return exp;
 82	  const rows = await store.listForUser(userId);
 83	  if (rows.filter((r) => isActive(r, now)).length >= MAX_ACTIVE_KEYS) return { ok: false, error: `You can have ${MAX_ACTIVE_KEYS} active keys. Revoke one first.` };
 84	  const m = newKeyMaterial();
 85	  const row = await store.insert({ userId, name: name.name, prefix: m.prefix, sha256: m.sha256, scopes: scopes.scopes, expiresAt: exp.at });
 86	  return { ok: true, key: m.key, view: toView(row, now) };
 87	}
 88	
 89	/** Resolve a presented key to its owner + scopes. Fails closed on anything malformed, revoked, expired or unknown. */
 90	export async function verifyKey(store: ApiKeyStore, presented: string, now = new Date()): Promise<{ userId: string; keyId: string; scopes: PersonalScope[] } | null> {
 91	  const m = KEY_RE.exec(String(presented ?? "").trim());
 92	  if (!m) return null;
 93	  const sha = sha256Hex(m[0]);
 94	  const row = await store.bySha(sha).catch(() => null);
 95	  if (!row || !isActive(row, now)) return null;
 96	  const a = Buffer.from(row.sha256, "hex"), b = Buffer.from(sha, "hex");
 97	  if (a.length !== b.length || !timingSafeEqual(a, b) || row.prefix !== m[1]) return null;
 98	  // last-used: at most one write per key per minute (the API can call this many times a second)
 99	  if (!row.lastUsedAt || now.getTime() - row.lastUsedAt.getTime() > 60_000) await store.touch(row.id, now).catch(() => {});
100	  return { userId: row.userId, keyId: row.id, scopes: toView(row, now).scopes };
101	}
