103	/** In-memory store (tests, previews). */
104	export function memoryKeyStore(): ApiKeyStore & { rows: ApiKeyRow[] } {
105	  const rows: ApiKeyRow[] = []; let n = 0;
106	  return {
107	    rows,
108	    async listForUser(u) { return rows.filter((r) => r.userId === u).sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime()); },
109	    async insert(r) { const row: ApiKeyRow = { ...r, id: `k${++n}`, createdAt: new Date(), lastUsedAt: null, revokedAt: null }; rows.push(row); return row; },
110	    async revoke(u, id, at) { const r = rows.find((x) => x.id === id && x.userId === u && !x.revokedAt); if (!r) return false; r.revokedAt = at; return true; },
111	    async bySha(s) { return rows.find((r) => r.sha256 === s) ?? null; },
112	    async touch(id, at) { const r = rows.find((x) => x.id === id); if (r) r.lastUsedAt = at; },
113	  };
114	}
115	// Cyrus customer app (r39): the switch. OFF unless CYRUS_CUSTOMER_APP=1; even then every page also needs the
116	// studio viewer gate (preview accounts until the studios go public). Pure: no host, no Nxeon imports.
117	export const CUSTOMER_APP_FLAG = "CYRUS_CUSTOMER_APP";
118	
119	export const customerAppEnabled = (env: Record<string, string | undefined> = process.env) => env[CUSTOMER_APP_FLAG] === "1";
120	
121	/** Public paths on the Cyrus host (cyrus.my) -> the app's internal tree. Used by the dual-host routing. */
122	export const APP_BASE = "/dashboard/cyrus/app";
123	export const CYRUS_APP_PATHS: Record<string, string> = {
124	  "/home": APP_BASE,
125	  "/new": `${APP_BASE}/new`,
126	  "/account": `${APP_BASE}/account`,
127	  "/projects": `${APP_BASE}/projects`,
128	};
129	
130	/** cyrus.my public path for an internal app path (identity elsewhere): used for links that must work on both hosts. */
131	export function appHref(path: string, onCyrusHost: boolean): string {
132	  if (!onCyrusHost || !path.startsWith(APP_BASE)) return path;
133	  const rest = path.slice(APP_BASE.length);
134	  if (rest === "" || rest.startsWith("?")) return "/home" + rest;
135	  return rest;
136	}
137	// Prisma-backed stores for the customer app (r39), through the Cyrus db door (host seam). SERVER ONLY.
138	import { cyrusDb } from "../db";
139	import type { ApiKeyStore } from "./apikeys";
140	import type { DataRequestStore } from "./data-requests";
141	
142	export const prismaKeyStore: ApiKeyStore = {
143	  listForUser: (userId) => cyrusDb.cyrusPersonalApiKey.findMany({ where: { userId }, orderBy: { createdAt: "desc" }, take: 100 }),
144	  insert: (r) => cyrusDb.cyrusPersonalApiKey.create({ data: r }),
145	  async revoke(userId, id, at) { const n = await cyrusDb.cyrusPersonalApiKey.updateMany({ where: { id, userId, revokedAt: null }, data: { revokedAt: at } }); return n.count > 0; },
146	  bySha: (sha256) => cyrusDb.cyrusPersonalApiKey.findUnique({ where: { sha256 } }),
147	  async touch(id, at) { await cyrusDb.cyrusPersonalApiKey.update({ where: { id }, data: { lastUsedAt: at } }); },
148	};
149	
150	export const prismaDataStore: DataRequestStore = {
151	  listForUser: (userId) => cyrusDb.cyrusDataRequest.findMany({ where: { userId }, orderBy: { createdAt: "desc" }, take: 50 }),
152	  insert: (r) => cyrusDb.cyrusDataRequest.create({ data: r }),
153	  async cancel(userId, id) { const n = await cyrusDb.cyrusDataRequest.updateMany({ where: { id, userId, status: "requested" }, data: { status: "cancelled" } }); return n.count > 0; },
154	};
155	// Customer app gate (r39), SERVER ONLY. Fail closed: the switch (CYRUS_CUSTOMER_APP=1) AND the studio viewer gate
156	// (preview accounts until the studios open) must both say yes, else the route 404s as if it did not exist.
157	// Every page and every server action calls appViewer() itself; nothing trusts the layout alone.
158	import { notFound } from "next/navigation";
159	import type { User } from "@prisma/client";
160	import { onCyrusHost } from "@/lib/auth";
161	import { bridgeConfig } from "@/lib/cyrus/bridge/config";
162	import { studioViewer } from "@/lib/cyrus/studios/deps";
163	import { customerAppEnabled, appHref, APP_BASE } from "@/lib/cyrus/app/flags";
164	
165	export type AppViewer = { user: User; onCyrus: boolean; nxeon: string; href: (internalPath: string) => string };
166	
167	export async function appViewerOrNull(): Promise<AppViewer | null> {
168	  if (!customerAppEnabled()) return null;
169	  const v = await studioViewer().catch(() => null);
170	  if (!v) return null;
171	  const onCyrus = await onCyrusHost();
172	  return { user: v.user, onCyrus, nxeon: bridgeConfig().nxeonOrigin, href: (p) => appHref(p, onCyrus) };
173	}
174	
175	export async function appViewer(): Promise<AppViewer> {
176	  const v = await appViewerOrNull();
177	  if (!v) notFound();
178	  return v;
179	}
