181	export const P = {
182	  home: APP_BASE, new: `${APP_BASE}/new`, projects: `${APP_BASE}/projects`, account: `${APP_BASE}/account`,
183	  project: (rootId: string) => `${APP_BASE}/projects/${encodeURIComponent(rootId)}`,
184	};
185	/** The existing studio pages (same on both hosts: /dashboard/cyrus passes through on cyrus.my). */
186	export const studioHref = (buildId?: string | null, studio?: string) =>
187	  !buildId ? "/dashboard/cyrus" : studio ? `/dashboard/cyrus/${encodeURIComponent(buildId)}/studio/${studio}` : `/dashboard/cyrus/${encodeURIComponent(buildId)}`;
188	// Customer app grants provider (r39): the r38 Nxeon grants (per-server consent at /dashboard/connect/cyrus) seen
189	// through the lib/cyrus/app/grants interface. App layer on purpose: lib/cyrus may not import lib/nxeon-platform
190	// (host seam). Off (CYRUS_SERVER_GRANTS unset) = unavailableGrants: the UI shows the contract, no fake connection.
191	// SERVER ONLY.
192	import { grantsEnabled, grantStore, revokeGrant } from "@/lib/nxeon-platform/grants";
193	import { platformEventSink } from "@/lib/nxeon-platform/events";
194	import { unavailableGrants, type GrantScope, type GrantsProvider } from "@/lib/cyrus/app/grants";
195	
196	export function appGrants(nxeonOrigin: string): GrantsProvider {
197	  if (!grantsEnabled()) return unavailableGrants;
198	  return {
199	    async state(userId) {
200	      const store = await grantStore();
201	      const rows = await store.listForUser("cyrus", userId);
202	      return {
203	        available: true,
204	        grants: rows.filter((g) => g.status === "active").map((g) => ({ serverId: g.serverId, scopes: g.scopes as GrantScope[], grantedAt: g.createdAt.toISOString(), lastUsedAt: null })),
205	        connectUrl: (serverId) => `${nxeonOrigin}/dashboard/connect/cyrus?server=${encodeURIComponent(serverId)}`,
206	      };
207	    },
208	    async revoke(userId, serverId) {
209	      const store = await grantStore();
210	      const g = await store.active("cyrus", userId, serverId);
211	      if (!g || g.userId !== userId) return false;
212	      return !!(await revokeGrant(store, { userId, grantId: g.id, by: `user:${userId}`, onEvent: platformEventSink() }));
213	    },
214	  };
215	}
