217	// Account server actions (r39). Every action re-runs the app gate (fail closed) and acts only on the viewer's own
218	// rows; ids from the client are only ever used together with the viewer's user id.
219	import { checkRateLimit } from "@/lib/rate-limit";
220	import { db } from "@/lib/db";
221	import { createKey, toView, type ApiKeyView } from "@/lib/cyrus/app/apikeys";
222	import { prismaDataStore, prismaKeyStore } from "@/lib/cyrus/app/store";
223	import { prefsFromForm } from "@/lib/cyrus/notify/events";
224	import { savePrefs } from "@/lib/cyrus/notify";
225	import { requestData } from "@/lib/cyrus/app/data-requests";
