229	type R<T = object> = ({ ok: true } & T) | { ok: false; error: string };
230	const NOPE = { ok: false as const, error: "Not found." };
231	const limited = (key: string, max: number) => { const r = checkRateLimit(key, { max, windowMs: 60_000 }); return r.ok ? null : { ok: false as const, error: `Too many requests. Try again in ${r.retryAfterSec}s.` }; };
232	const audit = (userId: string, action: string, detail: string) => db.auditLog.create({ data: { userId, action, detail } }).catch(() => {});
233	
234	export async function createApiKeyAction(input: { name: string; scopes: string[]; expiryDays: number }): Promise<R<{ key: string; view: ApiKeyView }>> {
235	  const v = await appViewerOrNull(); if (!v) return NOPE;
236	  const rl = limited(`cyrus:app:key:${v.user.id}`, 6); if (rl) return rl;
237	  const r = await createKey(prismaKeyStore, v.user.id, input);
238	  if (!r.ok) return r;
239	  await audit(v.user.id, "cyrus.apikey.create", `${r.view.id} ${r.view.prefix} [${r.view.scopes.join(",")}]`);
240	  return { ok: true, key: r.key, view: r.view };
241	}
242	
243	export async function revokeApiKeyAction(id: string): Promise<R<{ keys: ApiKeyView[] }>> {
244	  const v = await appViewerOrNull(); if (!v) return NOPE;
245	  const rl = limited(`cyrus:app:keyrev:${v.user.id}`, 20); if (rl) return rl;
246	  const ok = await prismaKeyStore.revoke(v.user.id, String(id).slice(0, 64), new Date());
247	  if (!ok) return { ok: false, error: "That key is already revoked or does not exist." };
248	  await audit(v.user.id, "cyrus.apikey.revoke", String(id).slice(0, 64));
249	  const now = new Date();
250	  return { ok: true, keys: (await prismaKeyStore.listForUser(v.user.id)).map((k) => toView(k, now)) };
251	}
252	
253	export async function savePrefsAction(fields: [string, string][]): Promise<R> {
254	  const v = await appViewerOrNull(); if (!v) return NOPE;
255	  const rl = limited(`cyrus:app:prefs:${v.user.id}`, 20); if (rl) return rl;
256	  const m = new Map(fields.slice(0, 100));
257	  const ok = await savePrefs(v.user.id, prefsFromForm((k) => m.get(k) ?? null));
258	  return ok ? { ok: true } : { ok: false, error: "Could not save." };
259	}
260	
261	export async function requestDataAction(input: { kind: string; confirm?: string; note?: string }): Promise<R> {
262	  const v = await appViewerOrNull(); if (!v) return NOPE;
263	  const rl = limited(`cyrus:app:data:${v.user.id}`, 5); if (rl) return rl;
264	  const r = await requestData(prismaDataStore, v.user.id, input);
265	  if (!r.ok) return r;
266	  await audit(v.user.id, `cyrus.data.${r.row.kind}.request`, r.row.id);
267	  return { ok: true };
268	}
269	
270	export async function cancelDataRequestAction(id: string): Promise<R> {
271	  const v = await appViewerOrNull(); if (!v) return NOPE;
272	  const ok = await prismaDataStore.cancel(v.user.id, String(id).slice(0, 64));
273	  return ok ? { ok: true } : { ok: false, error: "Only a request that has not started can be cancelled." };
274	}
275	
276	export async function revokeGrantAction(serverId: string): Promise<R> {
277	  const v = await appViewerOrNull(); if (!v) return NOPE;
278	  const ok = await appGrants(v.nxeon).revoke(v.user.id, String(serverId).slice(0, 64)).catch(() => false);
279	  if (ok) await audit(v.user.id, "cyrus.grant.revoke", String(serverId).slice(0, 64));
280	  return ok ? { ok: true } : { ok: false, error: "Nothing to revoke on that server." };
281	}

