 18	/** Read calls by personal keys: one audit row per key + operation per 10 minutes (writes are audited per call by runWrite). */
 19	const readAuditSeen = new Map<string, number>();
 20	export function shouldAuditPersonalRead(keyId: string, op: string, nowMs: number, seen = readAuditSeen): boolean {
 21	  const k = `${keyId}:${op}`, last = seen.get(k);
 22	  if (last !== undefined && nowMs - last < 600_000) return false;
 23	  if (seen.size > 5000) seen.clear();
 24	  seen.set(k, nowMs);
 25	  return true;
