 34	/** A memory index over a CatalogEntry JSONL file; invalid lines are skipped, a too-large or missing file = no catalog. */
 35	export async function fileCatalog(file: string | null): Promise<CatalogIndex | null> {
 36	  if (!file) return null;
 37	  let st;
 38	  try { st = statSync(file); } catch { return null; }
 39	  if (!st.isFile() || st.size > CATALOG_FILE_MAX_BYTES) return null;
 40	  const key = `${file}:${st.size}:${st.mtimeMs}`;
 41	  if (catalogCache?.key === key) return catalogCache.index;
 42	  const entries = [];
 43	  for (const line of readFileSync(file, "utf8").split("\n")) {
 44	    if (!line.trim()) continue;
 45	    try { const v = validateCatalogEntry(JSON.parse(line)); if (v.ok) entries.push(v.entry); } catch { /* skip */ }
 46	  }
 47	  const index = createMemoryCatalogIndex(entries);
 48	  catalogCache = { key, index };
 49	  return index;
 50	}
