177	// Cyrus API v1 idempotency for writes. A write carries `Idempotency-Key`; the first request with a key runs, every
178	// later one with the SAME key and the SAME request gets the first response back (header idempotent-replay: true), the
179	// same key with a DIFFERENT request is refused (422 idempotency_mismatch), and a key whose first request is still
180	// running answers 409 idempotency_in_flight. Scope = token key + subject + operation + key, so two clients never collide.
181	// 5xx answers are not stored (the caller may retry). Pure; the memory store is one process only. The table for a
182	// multi-instance store is proposed in prisma/manual-migration-cyrus-api-v1.sql (NOT run).
183	import { createHash } from "node:crypto";
184	
185	export const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_.:-]{8,128}$/;
186	/** OWNER: retention (proposed 24 h, same as the webhook replay window). */
187	export const IDEMPOTENCY_TTL_MS = 24 * 3600_000;
188	
189	export type StoredReply = { status: number; body: unknown };
190	export type IdempotencyBegin = { state: "new" } | { state: "replay"; reply: StoredReply } | { state: "mismatch" } | { state: "in_flight" };
191	export interface IdempotencyStore {
192	  begin(scope: string, requestHash: string, nowMs: number): Promise<IdempotencyBegin>;
193	  finish(scope: string, reply: StoredReply, nowMs: number): Promise<void>;
194	  /** the first request failed (5xx/throw): forget the key so a retry runs again */
195	  abort(scope: string): Promise<void>;
196	}
197	
198	export const requestHash = (method: string, path: string, body: string) => createHash("sha256").update(`${method.toUpperCase()}\n${path}\n${body}`).digest("hex");
199	
200	export function createMemoryIdempotencyStore(max = 20_000): IdempotencyStore & { size(): number } {
201	  const m = new Map<string, { hash: string; at: number; reply: StoredReply | null }>();
202	  const sweep = (now: number) => {
203	    for (const [k, v] of m) { if (v.at + IDEMPOTENCY_TTL_MS < now || m.size > max) m.delete(k); else break; }
204	  };
205	  return {
206	    async begin(scope, hash, now) {
207	      sweep(now);
208	      const hit = m.get(scope);
209	      if (!hit) { m.set(scope, { hash, at: now, reply: null }); return { state: "new" }; }
210	      if (hit.hash !== hash) return { state: "mismatch" };
211	      return hit.reply ? { state: "replay", reply: hit.reply } : { state: "in_flight" };
212	    },
213	    async finish(scope, reply, now) {
214	      const hit = m.get(scope);
215	      if (hit) { hit.reply = reply; hit.at = now; }
216	    },
217	    async abort(scope) { m.delete(scope); },
218	    size: () => m.size,
219	  };
220	}

