// Who may use the AI Mod Builder (Cyrus): private preview, feature "modbuilder", OR everyone with a
// verified account once the owner launches it (Setting cyrus_studio_public_enabled, default off).
// Both the effective user AND the real signed-in account must be on the
// allowlist, so impersonation can neither open it for someone else nor reveal
// it while the owner is looking at a customer's portal.
import { notFound } from "next/navigation";
import type { User } from "@prisma/client";
import { currentUser, realUser } from "../auth";
import { isPreviewUser } from "../preview-access";
import { getSettingBool } from "../settings";
import { publicMayBuild } from "../cyrus/launch-state";

export const CYRUS_STUDIO_PUBLIC_FLAG = "cyrus_studio_public_enabled";

export { studioDecision } from "./studio-decision";
import { studioDecision } from "./studio-decision";

/** The public launch flag. Fails CLOSED: a settings/DB error never opens the studio. */
export async function studioPublicEnabled(): Promise<boolean> {
  try {
    return await getSettingBool(CYRUS_STUDIO_PUBLIC_FLAG, false);
  } catch {
    return false;
  }
}

/**
 * The public may build only when the studio flag AND the token economy are both on (lib/cyrus/launch-state.ts).
 * Fails CLOSED on any settings/DB error.
 */
export async function studioPublicEffective(): Promise<boolean> {
  try {
    const [studioPublic, tokensLive] = await Promise.all([getSettingBool(CYRUS_STUDIO_PUBLIC_FLAG, false), getSettingBool("cyrus_tok_live", false)]);
    return publicMayBuild({ studioPublic, tokensLive });
  } catch {
    return false;
  }
}

export async function modBuilderUser(): Promise<User | null> {
  const [user, real] = await Promise.all([currentUser(), realUser()]);
  if (!user || !real || user.id !== real.id) return null;
  return modBuilderAccess(user);
}

/** The access rule alone, for an account that is not the session (Cyrus API v1 subject). Same decision as modBuilderUser. */
export async function modBuilderAccess(user: User): Promise<User | null> {
  // r40: a suspended Nxeon account (e.g. a Cyrus ban propagated to Nxeon) never acts through Cyrus, not even as an
  // API v1 subject (no session, so realUser()'s own suspended check does not run on that path). Fails closed.
  if (user.suspended) return null;
  const previewUser = await isPreviewUser(user, "modbuilder");
  const publicOn = previewUser ? false : await studioPublicEffective();
  return studioDecision({ previewUser, publicOn, emailVerified: !!user.emailVerifiedAt }) ? user : null;
}

/**
 * STRICT private preview only (never opened by the public launch): the old Mod Builder UI and anything else
 * that must stay owner-only after Cyrus goes public.
 */
export async function modBuilderPreviewUser(): Promise<User | null> {
  const [user, real] = await Promise.all([currentUser(), realUser()]);
  if (!user || !real || user.id !== real.id) return null;
  return (await isPreviewUser(user, "modbuilder")) ? user : null;
}

/** Pages: 404 for everyone outside the preview. */
export async function requireModBuilderUser(): Promise<User> {
  const u = await modBuilderUser();
  if (!u) notFound();
  return u;
}

/** Strict-preview page guard: 404 unless the viewer is on the private list (old Mod Builder UI). */
export async function requireModBuilderPreviewUser(): Promise<User> {
  const u = await modBuilderPreviewUser();
  if (!u) notFound();
  return u;
}

