export type DeliveryApiDeps = {
  env: Env;
  currentUser(): Promise<{ id: string } | null>;
  rateLimit(key: string, max: number, windowMs: number): { ok: boolean; retryAfterSec: number };
  /** The caller's OWN build, or null. */
  build(userId: string, buildId: string): Promise<DeliveryBuild | null>;
  /** The caller's OWN Cyrus project, or null. */
  project(userId: string, projectId: string): Promise<{ id: string; rootBuildId: string | null } | null>;
  /** deliver: the host's install checks (same as the install route). */
  checkInstall(a: { userId: string; build: DeliveryBuild; serverId: string; acked: string[]; acceptCapabilities: string | null }): Promise<HostCheck>;
  /** uninstall / Mod Packs: the server is the caller's, a Minecraft server, running, not being deleted. */
  checkServer(a: { userId: string; serverId: string }): Promise<HostCheck>;
  enqueue(a: EnqueueInput): Promise<EnqueueResult>;
  /** A delivery job on one of the caller's servers, or null. */
  job(userId: string, jobId: string): Promise<DeliveryJobRow | null>;
  jobs(userId: string, f: { serverId?: string; limit: number }): Promise<DeliveryJobRow[]>;
};

/** OWNER: tune. Per account. */
export const DELIVERY_RATE_LIMITS: [string, number, number][] = [["cyrus:deliver:min", 6, 60_000], ["cyrus:deliver:hour", 40, 3_600_000]];
const STATUS_RATE: [string, number, number] = ["cyrus:deliver:status", 120, 60_000];
const ID = /^[A-Za-z0-9_-]{1,64}$/;

const json = (status: number, body: unknown) => new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json", "cache-control": "no-store", "x-robots-tag": "noindex" } });
const NOT_FOUND = () => json(404, { error: "Not found" });
export const deliveryEnabled = (env: Env) => env[DELIVERY_FLAG] === "1";

async function gate(d: DeliveryApiDeps, rl: [string, number, number][]): Promise<{ ok: true; uid: string } | { ok: false; res: Response }> {
  if (!deliveryEnabled(d.env)) return { ok: false, res: NOT_FOUND() };
  const user = await d.currentUser().catch(() => null);
  if (!user) return { ok: false, res: NOT_FOUND() };
  for (const [k, max, win] of rl) {
    const r = d.rateLimit(`${k}:${user.id}`, max, win);
    if (!r.ok) return { ok: false, res: json(429, { error: `Too many requests. Retry in ${r.retryAfterSec}s.`, code: "rate_limited" }) };
  }
  return { ok: true, uid: user.id };
}

export type DeliveryRequestBody = { op?: unknown; buildId?: unknown; projectId?: unknown; serverId?: unknown; restartPolicy?: unknown; acked?: unknown; acceptCapabilities?: unknown; preview?: unknown };
export const readAcks = (v: unknown): string[] => (Array.isArray(v) ? [...new Set(v.filter((a): a is string => typeof a === "string" && /^[A-Za-z0-9_.:/-]{1,160}$/.test(a)))].slice(0, MAX_ACKS) : []);

/**
 * POST /api/cyrus/delivery/v1
 *   { op: "deliver", buildId, serverId, restartPolicy?: "now"|"next_restart", acked?: string[], acceptCapabilities?, preview? }
 *   { op: "uninstall", projectId, serverId, restartPolicy?, acked?, preview? }
 * Header `Idempotency-Key` (optional, 8..128 chars): the same key always answers with the same job.
 * preview: true runs every check and returns what would be delivered + the acknowledgements needed, enqueues nothing.
 */
export async function handleRequestDelivery(req: Request, d: DeliveryApiDeps): Promise<Response> {
  const g = await gate(d, DELIVERY_RATE_LIMITS);
  if (!g.ok) return g.res;
  const uid = g.uid;
  const body = (await req.json().catch(() => null)) as DeliveryRequestBody | null;
  if (!body || typeof body !== "object") return json(400, { error: "Send a JSON body.", code: "bad_body" });
  const op = body.op === "uninstall" ? "uninstall" : body.op === "deliver" || body.op === undefined ? "deliver" : null;
  if (!op) return json(400, { error: "op must be deliver or uninstall (Mod Packs have their own routes).", code: "bad_op" });
  const serverId = typeof body.serverId === "string" && ID.test(body.serverId) ? body.serverId : null;
  if (!serverId) return json(400, { error: "Pick a server.", code: "bad_server" });
  if (body.restartPolicy !== undefined && body.restartPolicy !== "now" && body.restartPolicy !== "next_restart") return json(400, { error: "restartPolicy must be now or next_restart.", code: "bad_policy" });
  const restartPolicy: RestartPolicy = body.restartPolicy === "next_restart" ? "next_restart" : "now";
  const acked = readAcks(body.acked);

  1	// Data export / deletion requests (r39). A request is recorded; r44's jobs run it (./data-jobs.ts, CYRUS_DATA_JOBS).
  2	// Rules: one open request per kind; a deletion needs the typed confirmation; Cyrus data only (the Nxeon account,
  3	// invoices and servers are Nxeon's and have their own process).
  4	import { graceUntilFor } from "./data-jobs";
  5	export const DATA_KINDS = ["export", "delete"] as const;
  6	export type DataKind = (typeof DATA_KINDS)[number];
  7	export const OPEN_STATUSES = ["requested", "in_progress"] as const;
  8	export type DataRequestRow = { id: string; userId: string; kind: string; status: string; note: string | null; createdAt: Date; completedAt: Date | null; graceUntil?: Date | null; expiresAt?: Date | null; archivePath?: string | null };
  9	
 10	export interface DataRequestStore {
 11	  listForUser(userId: string): Promise<DataRequestRow[]>;
 12	  insert(r: { userId: string; kind: DataKind; note: string | null; graceUntil?: Date | null }): Promise<DataRequestRow>;
 13	  cancel(userId: string, id: string): Promise<boolean>;
 14	}
