 16	export const DELETE_CONFIRM = "delete my cyrus data";
 17	
 18	export async function requestData(store: DataRequestStore, userId: string, input: { kind: unknown; confirm?: unknown; note?: unknown }, now = new Date()):
 19	  Promise<{ ok: true; row: DataRequestRow } | { ok: false; error: string }> {
 20	  const kind = String(input.kind ?? "");
 21	  if (!(DATA_KINDS as readonly string[]).includes(kind)) return { ok: false, error: "Unknown request." };
 22	  if (kind === "delete" && String(input.confirm ?? "").trim().toLowerCase() !== DELETE_CONFIRM) return { ok: false, error: `Type "${DELETE_CONFIRM}" to confirm.` };
 23	  const open = (await store.listForUser(userId)).find((r) => r.kind === kind && (OPEN_STATUSES as readonly string[]).includes(r.status));
 24	  if (open) return { ok: false, error: kind === "export" ? "An export is already on its way." : "A deletion request is already open." };
 25	  const note = String(input.note ?? "").replace(/[\u0000-\u001f\u007f]/g, " ").trim().slice(0, 500) || null;
 26	  // r44: a deletion waits DELETE_GRACE_DAYS (cancellable) before the job runs it
 27	  return { ok: true, row: await store.insert({ userId, kind: kind as DataKind, note, graceUntil: graceUntilFor(kind, now) }) };
 28	}
