 30	export function memoryDataStore(): DataRequestStore & { rows: DataRequestRow[] } {
 31	  const rows: DataRequestRow[] = []; let n = 0;
 32	  return {
 33	    rows,
 34	    async listForUser(u) { return rows.filter((r) => r.userId === u); },
 35	    async insert(r) { const row: DataRequestRow = { ...r, graceUntil: r.graceUntil ?? null, id: `d${++n}`, status: "requested", createdAt: new Date(), completedAt: null }; rows.push(row); return row; },
 36	    async cancel(u, id) { const r = rows.find((x) => x.id === id && x.userId === u && x.status === "requested"); if (!r) return false; r.status = "cancelled"; return true; },
 37	  };
