 39	// Cyrus data export + deletion JOBS (r44). r39 only recorded requests; this runs them. Pure core + deps (tests pass
 40	// fakes; ./data-jobs.server.ts wires Prisma, disk, gdpr and the host). Inert unless CYRUS_DATA_JOBS=1 on the worker.
 41	//
 42	// Status states (honest: the customer sees exactly these):
 43	//   export   requested -> in_progress -> ready (download for EXPORT_TTL_DAYS) -> expired        | failed (retried 3x)
 44	//   delete   requested (grace: cancellable until graceUntil) -> in_progress -> done             | failed (retried 3x)
 45	//            requested + note "waiting" when the grace is over but CYRUS_GDPR_ERASE is off: nothing is deleted.
 46	// Cascade rules for a deletion (policy per table: lib/cyrus/admin/ops.ts CYRUS_GDPR_TABLES):
 47	//   - projects, revisions, project assets, drafts, pages, posts, stars, keys, notification prefs: deleted
 48	//   - builds: anonymised (prompt cleared; the token-charge rows behind them stay: financial)
 49	//   - token ledger / lots / plan: retained (financial), keyed to the user id the platform keeps anyway
 50	//   - library contributions: PUBLISHED entries stay in the library under their licence with the contributor id cleared
 51	//     (the takedown/ownership rule: the owner can still take one down; projects and mods that use it keep working from
 52	//     their own copy, lib/cyrus/library/backend/moderation.ts). Contributions not yet published are removed.
 53	//   - server grants: revoked on the platform side
 54	//   - export archives of the person: removed from disk
 55	export const EXPORT_TTL_DAYS = 7;
 56	export const DELETE_GRACE_DAYS = 14;
 57	export const MAX_ATTEMPTS = 3;
 58	const DAY = 86_400_000;
 59	
 60	export type JobRow = {
 61	  id: string; userId: string; kind: string; status: string; note: string | null; createdAt: Date; completedAt: Date | null;
 62	  graceUntil?: Date | null; expiresAt?: Date | null; archivePath?: string | null; archiveBytes?: number | null; archiveSha256?: string | null;
 63	  attempts?: number; error?: string | null; result?: unknown;
 64	};
 65	export type JobPatch = Partial<Pick<JobRow, "status" | "note" | "completedAt" | "expiresAt" | "archivePath" | "archiveBytes" | "archiveSha256" | "attempts" | "error" | "result">> & { startedAt?: Date };
 66	
 67	export type DataJobDeps = {
 68	  now(): Date;
 69	  /** oldest first: exports in `requested`; deletions in `requested` whose grace is over; ready exports past expiresAt */
 70	  due(now: Date): Promise<{ exports: JobRow[]; deletes: JobRow[]; expired: JobRow[] }>;
 71	  /** atomic from-status -> patch; false = someone else took it (two workers never run one job) */
 72	  claim(id: string, from: string, patch: JobPatch): Promise<boolean>;
 73	  update(id: string, patch: JobPatch): Promise<void>;
 74	  collect(userId: string): Promise<{ files: { path: string; content: string }[]; counts: Record<string, number> }>;
 75	  writeArchive(row: JobRow, files: { path: string; content: string }[]): Promise<{ path: string; bytes: number; sha256: string }>;
 76	  removeFile(path: string): Promise<void>;
 77	  /** paths of every archive this person has on disk (deleted with their data) */
 78	  archivesOf(userId: string): Promise<string[]>;
 79	  eraseEnabled(): boolean;
 80	  erase(userId: string): Promise<{ deleted: Record<string, number>; anonymised: Record<string, number>; retained: Record<string, number>; anonId: string; salt: string }>;
 81	  /** the parts gdprErase does not own: keys, notification prefs + inbox, grants, unpublished contributions */
 82	  eraseExtras(userId: string): Promise<Record<string, number>>;
 83	  audit(e: { userId: string; action: string; target: string; detail: Record<string, unknown> }): Promise<void>;
 84	  log?(m: string): void;
 85	};
 86	
 87	export type TickResult = { exported: number; deleted: number; expired: number; waiting: number; failed: number };
 88	
 89	const errText = (e: unknown) => String((e as Error)?.message ?? e).replace(/postgres(ql)?:\/\/\S+/g, "<db>").slice(0, 300);
 90	
 91	export async function runExport(row: JobRow, d: DataJobDeps): Promise<"ready" | "failed" | "skipped"> {
 92	  const now = d.now();
 93	  const attempts = (row.attempts ?? 0) + 1;
 94	  if (!(await d.claim(row.id, "requested", { status: "in_progress", startedAt: now, attempts, error: null }))) return "skipped";
 95	  try {
 96	    const { files, counts } = await d.collect(row.userId);
 97	    const a = await d.writeArchive(row, files);
 98	    await d.update(row.id, { status: "ready", archivePath: a.path, archiveBytes: a.bytes, archiveSha256: a.sha256, completedAt: d.now(), expiresAt: new Date(d.now().getTime() + EXPORT_TTL_DAYS * DAY), result: { counts } });
 99	    await d.audit({ userId: row.userId, action: "cyrus.data.export.ready", target: row.id, detail: { bytes: a.bytes, sha256: a.sha256, counts } });
100	    return "ready";
101	  } catch (e) {
102	    const final = attempts >= MAX_ATTEMPTS;
103	    await d.update(row.id, { status: final ? "failed" : "requested", error: errText(e) }).catch(() => {});
104	    await d.audit({ userId: row.userId, action: "cyrus.data.export.error", target: row.id, detail: { attempts, final, error: errText(e) } }).catch(() => {});
105	    return "failed";
106	  }
107	}
108	
109	export async function runDelete(row: JobRow, d: DataJobDeps): Promise<"done" | "waiting" | "failed" | "skipped"> {
110	  const now = d.now();
111	  // a request recorded before r44 has no grace date: it gets the full grace from when it was made
112	  const grace = row.graceUntil ?? new Date(row.createdAt.getTime() + DELETE_GRACE_DAYS * DAY);
113	  if (grace > now) return "skipped";
114	  if (!d.eraseEnabled()) {
115	    if (row.note !== "waiting") await d.update(row.id, { note: "waiting" }).catch(() => {});
116	    return "waiting";
117	  }
118	  const attempts = (row.attempts ?? 0) + 1;
119	  if (!(await d.claim(row.id, "requested", { status: "in_progress", startedAt: now, attempts, error: null }))) return "skipped";
120	  try {
121	    const extras = await d.eraseExtras(row.userId);
122	    const r = await d.erase(row.userId);
123	    let archives = 0;
124	    for (const p of await d.archivesOf(row.userId)) { await d.removeFile(p).catch(() => {}); archives++; }
125	    const result = { deleted: r.deleted, anonymised: r.anonymised, retained: r.retained, extras, archives, anonId: r.anonId };
126	    await d.update(row.id, { status: "done", note: null, completedAt: d.now(), result });
127	    // the salt lives only in the audit row (re-identifying anonymised rows needs it; staff only)
128	    await d.audit({ userId: row.userId, action: "cyrus.data.delete.done", target: row.id, detail: { ...result, salt: r.salt } });
129	    return "done";
130	  } catch (e) {
131	    const final = attempts >= MAX_ATTEMPTS;
132	    await d.update(row.id, { status: final ? "failed" : "requested", error: errText(e) }).catch(() => {});
133	    await d.audit({ userId: row.userId, action: "cyrus.data.delete.error", target: row.id, detail: { attempts, final, error: errText(e) } }).catch(() => {});
134	    return "failed";
135	  }
136	}
