138	/** One worker tick: expire old archives, then at most `max` exports and `max` deletions, oldest first. Never throws. */
139	export async function dataJobsTick(d: DataJobDeps, max = 3): Promise<TickResult> {
140	  const out: TickResult = { exported: 0, deleted: 0, expired: 0, waiting: 0, failed: 0 };
141	  let due: Awaited<ReturnType<DataJobDeps["due"]>>;
142	  try { due = await d.due(d.now()); } catch (e) { d.log?.(`[cyrus-data-jobs] due: ${errText(e)}`); return out; }
143	  for (const r of due.expired) {
144	    const file = r.archivePath;
145	    if (!(await d.claim(r.id, "ready", { status: "expired", archivePath: null }).catch(() => false))) continue;
146	    if (file) await d.removeFile(file).catch(() => {});
147	    out.expired++;
148	  }
149	  for (const r of due.exports.slice(0, max)) { const s = await runExport(r, d); if (s === "ready") out.exported++; else if (s === "failed") out.failed++; }
150	  for (const r of due.deletes.slice(0, max)) { const s = await runDelete(r, d); if (s === "done") out.deleted++; else if (s === "waiting") out.waiting++; else if (s === "failed") out.failed++; }
151	  return out;
152	}
