154	/** Owner-only download check: the archive exists only while `ready` and unexpired, and only for its own user. */
155	export function downloadable(row: JobRow | null, userId: string, now: Date): row is JobRow & { archivePath: string } {
156	  return !!row && row.userId === userId && row.kind === "export" && row.status === "ready" && !!row.archivePath && !!row.expiresAt && row.expiresAt > now;
157	}
