159	/** What the customer sees for a request (one line, no internals). */
160	export function statusLine(r: JobRow, now: Date): { pill: string; tone: "ok" | "wait" | "none" | "bad"; detail: string } {
161	  const d = (x: Date | null | undefined) => (x ? x.toISOString().slice(0, 10) : "");
162	  if (r.kind === "export") {
163	    if (r.status === "ready") return { pill: "ready", tone: "ok", detail: `download until ${d(r.expiresAt)}` };
164	    if (r.status === "expired") return { pill: "expired", tone: "none", detail: "the archive was removed; request a new one" };
165	    if (r.status === "in_progress") return { pill: "preparing", tone: "wait", detail: "building your archive" };
166	    if (r.status === "failed") return { pill: "failed", tone: "bad", detail: "we could not build it; support has been told" };
167	  } else {
168	    if (r.status === "requested" && r.graceUntil && r.graceUntil > now) return { pill: "scheduled", tone: "wait", detail: `deletes on ${d(r.graceUntil)}; you can cancel until then` };
169	    if (r.status === "requested" && r.note === "waiting") return { pill: "waiting", tone: "wait", detail: "queued for staff to run; nothing deleted yet" };
170	    if (r.status === "in_progress") return { pill: "deleting", tone: "wait", detail: "in progress" };
171	    if (r.status === "done") return { pill: "deleted", tone: "ok", detail: `finished ${d(r.completedAt)}` };
172	    if (r.status === "failed") return { pill: "failed", tone: "bad", detail: "stopped part way; support has been told" };
173	  }
174	  if (r.status === "cancelled") return { pill: "cancelled", tone: "none", detail: "" };
175	  return { pill: "queued", tone: "wait", detail: "" };
176	}
