218	export function dataJobDeps(env: Record<string, string | undefined> = process.env): DataJobDeps {
219	  const t = cyrusDb.cyrusDataRequest;
220	  return {
221	    now: () => new Date(),
222	    async due(now) {
223	      const [exports, deletes, expired] = await Promise.all([
224	        t.findMany({ where: { kind: "export", status: "requested" }, orderBy: { createdAt: "asc" }, take: 10 }),
225	        t.findMany({ where: { kind: "delete", status: "requested", OR: [{ graceUntil: { lte: now } }, { graceUntil: null, createdAt: { lte: new Date(now.getTime() - DELETE_GRACE_DAYS * 86_400_000) } }] }, orderBy: { createdAt: "asc" }, take: 10 }),
226	        t.findMany({ where: { kind: "export", status: "ready", expiresAt: { lte: now } }, take: 50 }),
227	      ]);
228	      return { exports, deletes, expired } as { exports: JobRow[]; deletes: JobRow[]; expired: JobRow[] };
229	    },
230	    async claim(id, from, patch) { return (await t.updateMany({ where: { id, status: from }, data: patch as never })).count === 1; },
231	    async update(id, patch: JobPatch) { await t.update({ where: { id }, data: patch as never }); },
232	    async collect(userId) {
233	      const u = await getHost().users.get(userId).catch(() => null);
234	      const g = await gdprExport(userId, u?.email ?? null);
235	      const tables = { ...(g.tables as Record<string, unknown[]>) };
236	      tables.cyrusNotificationPref = await cyrusDb.cyrusNotificationPref.findMany({ where: { userId } });
237	      tables.cyrusNotification = await cyrusDb.cyrusNotification.findMany({ where: { userId }, orderBy: { createdAt: "desc" }, take: CAP });
238	      tables.cyrusPersonalApiKey = await cyrusDb.cyrusPersonalApiKey.findMany({ where: { userId }, select: { id: true, name: true, prefix: true, scopes: true, createdAt: true, lastUsedAt: true, expiresAt: true, revokedAt: true } });
239	      tables.cyrusDataRequest = await t.findMany({ where: { userId }, select: { id: true, kind: true, status: true, createdAt: true, completedAt: true } });
240	      const gs = await grantsProvider().state(userId).catch(() => ({ available: false as const, reason: "error" }));
241	      tables.serverGrants = gs.available ? gs.grants : [{ note: "server grants are kept by Nxeon and were not reachable from this job; see Nxeon > Connected apps" }];
242	      const counts = Object.fromEntries(Object.entries(tables).map(([k, v]) => [k, Array.isArray(v) ? v.length : 0]));
243	      const files = [
244	        { path: "README.txt", content: README(counts) },
245	        { path: "export.json", content: json({ schema: "cyrus-data-export/1", subject: g.subject, exportedAt: g.exportedAt, truncated: g.truncated, counts }) },
246	        ...Object.entries(tables).map(([k, v]) => ({ path: `tables/${k}.json`, content: json(v) })),
247	      ];
248	      return { files, counts };
249	    },
250	    async writeArchive(row, files) {
251	      const dir = exportDir(env);
252	      await mkdir(dir, { recursive: true, mode: 0o700 });
253	      const buf = Buffer.from(await zipFiles(files).arrayBuffer());
254	      const p = path.join(dir, `${row.id.replace(/[^A-Za-z0-9_-]/g, "").slice(0, 64)}-${randomBytes(8).toString("hex")}.zip`);
255	      await writeFile(p, buf, { mode: 0o600, flag: "wx" });
