 59	// r44: the Postgres webhook OUTBOX ("CyrusWebhookOutbox", prisma/manual-migration-cyrus-api-v1.sql) + its metrics.
 60	// Selected with CYRUS_API_V1_WEBHOOK_STORE=sql (default: the in-process memory outbox, unchanged). SERVER ONLY.
 61	// Multi-worker safe: due() CLAIMS rows (FOR UPDATE SKIP LOCKED) by pushing nextAttemptAt out by a lease, so a second
 62	// dispatcher never sends the same row while the first is still waiting on it; markSent/markFailed end the lease.
 63	// Delivery stays at-least-once (a crash after the POST re-sends after the lease); receivers dedupe by event id.
 64	// HOST SEAM: raw SQL through the db handle the caller passes (cyrusDb in ./emit.ts).
 65	import type { OutboxRow, WebhookOutbox } from "./webhooks";
 66	
 67	export type RawSql = { $queryRawUnsafe<T = unknown>(q: string, ...a: unknown[]): Promise<T>; $executeRawUnsafe(q: string, ...a: unknown[]): Promise<number> };
 68	export const OUTBOX_LEASE_MS = 2 * 60_000;
 69	const T = `"CyrusWebhookOutbox"`;
 70	type Raw = { id: string; type: string; subject: string | null; body: string; attempts: number | bigint; nextAttemptAt: Date; status: string; lastError: string | null; createdAt: Date };
 71	const row = (r: Raw): OutboxRow => ({ id: r.id, type: r.type as OutboxRow["type"], subject: r.subject, body: r.body, attempts: Number(r.attempts), nextAttemptAt: new Date(r.nextAttemptAt), status: r.status as OutboxRow["status"], lastError: r.lastError, createdAt: new Date(r.createdAt) });
 72	
 73	export function createSqlWebhookOutbox(db: RawSql, leaseMs = OUTBOX_LEASE_MS): WebhookOutbox {
 74	  return {
 75	    async add(e) {
 76	      await db.$executeRawUnsafe(`INSERT INTO ${T} ("id","type","subject","body","nextAttemptAt","createdAt") VALUES ($1,$2,$3,$4,$5,$5) ON CONFLICT ("id") DO NOTHING`, e.id, e.type, e.subject, JSON.stringify(e), new Date(e.createdAt));
 77	    },
 78	    async due(now, limit) {
 79	      const rows = await db.$queryRawUnsafe<Raw[]>(
 80	        `UPDATE ${T} o SET "nextAttemptAt" = $3 FROM (SELECT "id" FROM ${T} WHERE "status" = 'pending' AND "nextAttemptAt" <= $1 ORDER BY "createdAt" ASC LIMIT $2 FOR UPDATE SKIP LOCKED) d
 81	         WHERE o."id" = d."id" RETURNING o."id", o."type", o."subject", o."body", o."attempts", o."nextAttemptAt", o."status", o."lastError", o."createdAt"`,
 82	        now, Math.max(1, Math.min(500, limit)), new Date(now.getTime() + leaseMs));
 83	      return rows.map(row).sort((a, b) => +a.createdAt - +b.createdAt);
 84	    },
 85	    async markSent(id, now) { await db.$executeRawUnsafe(`UPDATE ${T} SET "status" = 'sent', "lastError" = NULL, "sentAt" = $2 WHERE "id" = $1`, id, now); },
 86	    async markFailed(id, f) {
 87	      await db.$executeRawUnsafe(`UPDATE ${T} SET "attempts" = $2, "lastError" = $3, "nextAttemptAt" = COALESCE($4::timestamp, "nextAttemptAt"), "status" = CASE WHEN $4::timestamp IS NULL THEN 'dead' ELSE 'pending' END WHERE "id" = $1`, id, f.attempts, f.error, f.nextAttemptAt);
 88	    },
 89	  };
 90	}
