 94	/** Metrics for the admin reconciliation view and alerts (computed in SQL, so every process sees the same numbers). */
 95	export async function outboxMetrics(db: RawSql, now = new Date()): Promise<OutboxMetrics> {
 96	  const since = new Date(now.getTime() - 86_400_000);
 97	  const [agg] = await db.$queryRawUnsafe<{ pending: bigint | number; dead: bigint | number; sent24h: bigint | number; failed24h: bigint | number; oldest: Date | null }[]>(
 98	    `SELECT COUNT(*) FILTER (WHERE "status" = 'pending') AS pending, COUNT(*) FILTER (WHERE "status" = 'dead') AS dead,
 99	            COUNT(*) FILTER (WHERE "status" = 'sent' AND "sentAt" >= $1) AS sent24h,
100	            COUNT(*) FILTER (WHERE "lastError" IS NOT NULL AND "createdAt" >= $1) AS failed24h,
101	            MIN("createdAt") FILTER (WHERE "status" = 'pending') AS oldest FROM ${T}`, since);
102	  const types = await db.$queryRawUnsafe<{ type: string; status: string; n: bigint | number }[]>(`SELECT "type", "status", COUNT(*) AS n FROM ${T} WHERE "status" IN ('pending','dead') GROUP BY "type", "status"`);
103	  const byType: OutboxMetrics["byType"] = {};
104	  for (const t of types) { const b = (byType[t.type] ??= { pending: 0, dead: 0 }); if (t.status === "pending") b.pending = Number(t.n); else b.dead = Number(t.n); }
105	  return {
106	    pending: Number(agg?.pending ?? 0), dead: Number(agg?.dead ?? 0), sent24h: Number(agg?.sent24h ?? 0), failedAttempts24h: Number(agg?.failed24h ?? 0),
107	    oldestPendingAgeSec: agg?.oldest ? Math.max(0, Math.round((now.getTime() - new Date(agg.oldest).getTime()) / 1000)) : null, byType,
108	  };
109	}
110	// Cyrus -> caller (Nxeon) WEBHOOKS: event builders, a transactional-outbox interface, and the dispatcher that signs,
111	// sends and retries. Contract: the `webhooks` section of docs/api/cyrus-v1.openapi.yaml (schemas in ./schemas.ts).
112	//   headers  Cyrus-Webhook-Id, Cyrus-Webhook-Timestamp (unix s), Cyrus-Signature: v1=<hex HMAC-SHA256(secret, id.ts.body)>
113	//            (./signing.ts signWebhook; the receiver drops anything older than 300 s and any id it has seen in 24 h)
114	//   delivery at-least-once; 2xx = done; anything else (or no answer in 10 s) is retried after 1 m, 5 m, 30 m, 2 h, 12 h,
115	//            then the event is DEAD (kept for an admin to replay). Each event carries current state, never a delta, so
116	//            order between events does not matter.
