171	export type DispatchResult = { sent: number; retried: number; dead: number };
172	/** One pass (the worker calls it every minute or so): send what is due, schedule retries, bury what ran out of tries. */
173	export async function dispatchWebhooks(a: { outbox: WebhookOutbox; target: WebhookTarget; now?: () => Date; fetch?: typeof fetch; limit?: number }): Promise<DispatchResult> {
174	  const now = a.now ?? (() => new Date());
175	  const doFetch = a.fetch ?? fetch;
176	  const out: DispatchResult = { sent: 0, retried: 0, dead: 0 };
177	  for (const row of await a.outbox.due(now(), a.limit ?? 50)) {
178	    const ts = String(Math.floor(now().getTime() / 1000));
179	    let error: string | null = null;
180	    const ac = new AbortController();
181	    const timer = setTimeout(() => ac.abort(), WEBHOOK_TIMEOUT_MS);
182	    try {
183	      const res = await doFetch(a.target.url, {
184	        method: "POST", signal: ac.signal, redirect: "manual",
185	        headers: { "content-type": "application/json", "cyrus-webhook-id": row.id, "cyrus-webhook-timestamp": ts, "cyrus-signature": signWebhook(a.target.secret, row.id, ts, row.body), "user-agent": "cyrus-webhooks/1" },
186	        body: row.body,
187	      });
188	      if (res.status < 200 || res.status >= 300) error = `HTTP ${res.status}`;
189	    } catch (e) {
190	      error = ac.signal.aborted ? `no answer within ${WEBHOOK_TIMEOUT_MS} ms` : (e as Error).message || "network";
191	    } finally { clearTimeout(timer); }
192	    if (!error) { await a.outbox.markSent(row.id, now()); out.sent++; continue; }
193	    const attempts = row.attempts + 1;
194	    const delay = WEBHOOK_RETRY_DELAYS_MS[attempts - 1];
195	    await a.outbox.markFailed(row.id, { attempts, nextAttemptAt: delay === undefined ? null : new Date(now().getTime() + delay), error: error.slice(0, 300) });
196	    if (delay === undefined) out.dead++; else out.retried++;
197	  }
198	  return out;
199	}
