201	/** In-process outbox (tests, a single dev instance). */
202	export function createMemoryOutbox(): WebhookOutbox & { rows: Map<string, OutboxRow> } {
203	  const rows = new Map<string, OutboxRow>();
204	  return {
205	    rows,
206	    async add(e) {
207	      if (rows.has(e.id)) return;
208	      rows.set(e.id, { id: e.id, type: e.type, subject: e.subject, body: JSON.stringify(e), attempts: 0, nextAttemptAt: new Date(e.createdAt), status: "pending", lastError: null, createdAt: new Date(e.createdAt) });
209	    },
210	    async due(now, limit) {
211	      return [...rows.values()].filter((r) => r.status === "pending" && r.nextAttemptAt <= now).sort((x, y) => +x.createdAt - +y.createdAt).slice(0, limit);
212	    },
213	    async markSent(id) { const r = rows.get(id); if (r) { r.status = "sent"; r.lastError = null; } },
214	    async markFailed(id, f) {
215	      const r = rows.get(id);
216	      if (!r) return;
217	      r.attempts = f.attempts; r.lastError = f.error;
218	      if (f.nextAttemptAt) r.nextAttemptAt = f.nextAttemptAt; else r.status = "dead";
219	    },
220	  };
221	}
222	// NXEON SIDE: the receiver for Cyrus webhooks (Cyrus -> Nxeon). Framework-free (Request -> Response); a later Nxeon
223	// route (e.g. app/api/webhooks/cyrus/route.ts) wraps it. NOTHING mounts it today. Imports nothing from lib/cyrus.
224	// Checks, in order: body size -> headers present -> timestamp within 300 s -> HMAC-SHA256 signature (several "v1=" values
225	// allowed during a secret rotation, constant-time) -> exactly-once by event id (24 h) -> JSON envelope -> the handler.
226	// 2xx tells Cyrus "done"; a handler throw answers 500 so Cyrus retries (the id is released so the retry is processed).
227	import { createHmac, timingSafeEqual } from "node:crypto";
228	
229	export const CYRUS_WEBHOOK_EVENTS = ["build.finished", "mod.published", "install.result", "delivery.rolledback", "library.contributed"] as const;
230	export type CyrusWebhookType = (typeof CYRUS_WEBHOOK_EVENTS)[number];
231	export type CyrusWebhook = { id: string; type: CyrusWebhookType; createdAt: string; subject: string | null; data: Record<string, unknown> };
232	
233	export const RECEIVER_TOLERANCE_S = 300;
234	export const RECEIVER_MAX_BODY = 256 * 1024;
235	
236	/** Remembers processed ids (memory here; the CyrusWebhookReceipt table for several instances). */
237	export interface ReceiptStore {
238	  /** true when newly recorded; false when already seen */
239	  claim(id: string, type: string, nowMs: number): Promise<boolean>;
240	  release(id: string): Promise<void>;
241	}
242	export function createMemoryReceipts(ttlMs = 24 * 3600_000): ReceiptStore {
243	  const m = new Map<string, number>();
244	  return {
245	    async claim(id, _type, now) {
246	      for (const [k, t] of m) { if (t + ttlMs < now) m.delete(k); else break; }
247	      if (m.has(id)) return false;
248	      m.set(id, now);
249	      return true;
250	    },
251	    async release(id) { m.delete(id); },
252	  };
253	}
254	
255	export const expectedSignature = (secret: string, id: string, ts: string, body: string) => `v1=${createHmac("sha256", secret).update(`${id}.${ts}.${body}`).digest("hex")}`;
256	function same(a: string, b: string): boolean {
257	  const x = Buffer.from(a), y = Buffer.from(b);
258	  return x.length === y.length && timingSafeEqual(x, y);
259	}
