261	export type ReceiverOptions = {
262	  /** current secret, plus the previous one during a rotation */
263	  secrets: string[];
264	  receipts: ReceiptStore;
265	  handle: (e: CyrusWebhook) => Promise<void>;
266	  now?: () => number;
267	  log?: (m: string) => void;
268	};
269	
270	const reply = (status: number, body: Record<string, unknown>) => Response.json(body, { status, headers: { "cache-control": "no-store" } });
271	
272	export async function receiveCyrusWebhook(req: Request, o: ReceiverOptions): Promise<Response> {
273	  const now = (o.now ?? Date.now)();
274	  if (req.method !== "POST") return reply(405, { error: "method" });
275	  if (!o.secrets.some((s) => s.length >= 32)) return reply(503, { error: "receiver not configured" });
276	  const body = await req.text();
277	  if (body.length > RECEIVER_MAX_BODY) return reply(413, { error: "too large" });
278	  const id = req.headers.get("cyrus-webhook-id"), ts = req.headers.get("cyrus-webhook-timestamp"), sig = req.headers.get("cyrus-signature");
279	  if (!id || !/^[A-Za-z0-9_.:-]{4,128}$/.test(id) || !ts || !/^\d{9,11}$/.test(ts) || !sig) return reply(400, { error: "unsigned" });
280	  if (Math.abs(Math.floor(now / 1000) - Number(ts)) > RECEIVER_TOLERANCE_S) return reply(400, { error: "stale" });
281	  const sent = sig.split(/[ ,]+/).filter(Boolean);
282	  if (!o.secrets.filter((s) => s.length >= 32).some((s) => sent.some((v) => same(v, expectedSignature(s, id, ts, body))))) return reply(401, { error: "bad signature" });
283	  let e: CyrusWebhook;
284	  try {
285	    e = JSON.parse(body) as CyrusWebhook;
286	    if (!e || e.id !== id || !(CYRUS_WEBHOOK_EVENTS as readonly string[]).includes(e.type) || typeof e.data !== "object" || e.data === null) throw new Error("shape");
287	  } catch { return reply(400, { error: "bad envelope" }); }
288	  if (!(await o.receipts.claim(id, e.type, now))) return reply(200, { ok: true, duplicate: true });
289	  try {
290	    await o.handle(e);
291	    return reply(200, { ok: true });
292	  } catch (err) {
293	    await o.receipts.release(id);
294	    o.log?.(`[cyrus-webhook] ${e.type} ${id} failed: ${(err as Error).message}`);
295	    return reply(500, { error: "handler failed" });
296	  }
297	}
