299	/** r44: receipts in Postgres ("CyrusWebhookReceipt", prisma/manual-migration-cyrus-api-v1.sql) so every Nxeon instance
300	 *  sees the same processed ids: exactly-once handling across instances for 24 h (older rows are pruned on claim). */
301	export function createSqlReceipts(db: { $executeRawUnsafe(q: string, ...a: unknown[]): Promise<number> }, ttlMs = 24 * 3600_000): ReceiptStore {
302	  let lastPrune = 0;
303	  return {
304	    async claim(id, type, now) {
305	      if (now - lastPrune > 3600_000) { lastPrune = now; await db.$executeRawUnsafe(`DELETE FROM "CyrusWebhookReceipt" WHERE "receivedAt" < $1`, new Date(now - ttlMs)).catch(() => 0); }
306	      return (await db.$executeRawUnsafe(`INSERT INTO "CyrusWebhookReceipt" ("id","type","receivedAt") VALUES ($1,$2,$3) ON CONFLICT ("id") DO NOTHING`, id, type, new Date(now))) === 1;
307	    },
308	    async release(id) { await db.$executeRawUnsafe(`DELETE FROM "CyrusWebhookReceipt" WHERE "id" = $1`, id); },
309	  };
310	}
