    61	export type ConversionSweepResult = { sent: number; skipped: number; retried: number; failed: number };
    62	export async function conversionSweep(deps: ConversionDeps = prismaConversionDeps(), env: Env = process.env, now = new Date()): Promise<ConversionSweepResult> {
    63	  const out: ConversionSweepResult = { sent: 0, skipped: 0, retried: 0, failed: 0 };
    64	  if (!conversionsEnabled(env)) return out;
    65	  for (const r of await deps.due(50)) {
    66	    if (!deps.transport) { await deps.mark(r.id, { status: "skipped:no_transport" }); out.skipped++; continue; }
    67	    const snap = await deps.snapshot(r.userId).catch(() => null);
    68	    const p = conversionPayload({
    69	      id: r.kind as ConversionId, eventId: r.id, atMs: r.createdAt.getTime(), consent: parseConsent(snap?.consent), attribution: decodeAttribution(snap?.attr),
    70	      valueCents: r.valueCents, currency: r.currency ?? undefined, emailSha256: await deps.emailSha256(r.userId).catch(() => null),
    71	    });
    72	    if (!p) { await deps.mark(r.id, { status: "skipped:no_consent" }); out.skipped++; continue; }
    73	    let ok = false, err: string | null = null;
    74	    try { const [m, g] = await Promise.all([deps.transport.meta(p.meta), deps.transport.google(p.google, r.userId)]); ok = m || g; if (!ok) err = "no transport accepted it (not configured?)"; }
    75	    catch (e) { err = (e as Error).message.slice(0, 200); }
    76	    if (ok) { await deps.mark(r.id, { status: "sent", sentAt: now, lastError: null }); out.sent++; continue; }
    77	    const attempts = r.attempts + 1;
    78	    await deps.mark(r.id, { status: attempts >= CONVERSION_MAX_ATTEMPTS ? "failed" : "pending", attempts, lastError: err });
    79	    if (attempts >= CONVERSION_MAX_ATTEMPTS) out.failed++; else out.retried++;
    80	  }
    81	  return out;
    82	}
