  if (!/^[A-Za-z0-9_-]{1,64}$/.test(rootId)) notFound();
  // ownership: only this user's builds of this chain; a stranger's id is the same 404 as a missing one
  const rows = await cyrusDb.modBuild.findMany({ where: { userId: v.user.id, OR: [{ id: rootId }, { rootBuildId: rootId }] }, orderBy: { createdAt: "asc" }, take: 200 });
  if (!rows.some((r) => r.id === rootId)) notFound();
  const project = groupProjects(rows.map(toView)).find((p) => p.rootId === rootId);
  if (!project) notFound();
  const now = new Date();
  const head = project.head, headRow = head ? rows.find((r) => r.id === head.id)! : null;
