        { id: "bosses", label: "Bosses", on: designer }, { id: "config", label: "Config", on: !!config },
        { id: "datapacks", label: "Data packs", on: process.env[DATAPACK_STUDIO_FLAG] === "1" }, { id: "library", label: "Library", on: process.env[LIBRARY_BROWSE_FLAG] === "1" },
