      <header className="cx-head">
        <div>
          <div className="cx-eyebrow">Project</div>
          <h1 className="cx-h1">{project.title}</h1>
          <p className="cx-sub">{head ? <>Current version {head.version ? <b>v{head.version}</b> : "built"} for Minecraft {head.mcVersion}, {ago(head.finishedAt || head.createdAt, now)}.</> : "No finished build yet."} {project.builds.length} build{project.buil
        </div>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center" }}>
