          <a className="cx-btn cx-btn-pri" href={`${studioBase}/${encodeURIComponent(target)}`}>Open in studio</a>
        </div>
      </header>
  { id: "profile", label: "Profile" }, { id: "connections", label: "Nxeon and servers" }, { id: "keys", label: "API keys" },
  { id: "notifications", label: "Notifications" }, { id: "billing", label: "Plan and billing" }, { id: "data", label: "Your data" },
