 80	export type Normalised = { raster: Raster; notes: string[] };
 81	/** A game PNG -> a square 16/32/64 raster the studio can edit (pure apart from decoding). */
 82	export function normaliseGamePng(bytes: Buffer): Normalised | { error: string } {
 83	  const d = decodePng(bytes, GAME_PNG_LIMITS);
 84	  if (!d.ok) return { error: d.error };
 85	  const notes: string[] = [];
 86	  let { width: w, height: h } = d;
 87	  let px = d.raster.px;
 88	  // a vertical animation strip: keep the first frame
 89	  if (h > w && h % w === 0) { px = px.slice(0, w * w * 4); notes.push(`animation strip: the first of ${h / w} frames`); h = w; }
 90	  if (w !== h) return { error: `the texture is ${w}x${h}; the studio edits square 16, 32 or 64 px textures` };
 91	  let size = w;
 92	  while (size > 64 && size % 2 === 0) { // icons: halve (nearest) until it fits
 93	    const n = size / 2, out = new Uint8ClampedArray(n * n * 4);
 94	    for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) { const s = ((y * 2) * size + x * 2) * 4, t = (y * n + x) * 4; out[t] = px[s]; out[t + 1] = px[s + 1]; out[t + 2] = px[s + 2]; out[t + 3] = px[s + 3]; }
 95	    px = out; notes.push(`scaled ${size} px to ${n} px`); size = n;
 96	  }
 97	  if (![16, 32, 64].includes(size)) return { error: `the texture is ${size} px; the studio edits 16, 32 or 64 px textures` };
 98	  let soft = 0;
 99	  for (let i = 3; i < px.length; i += 4) if (px[i] !== 0 && px[i] !== 255) { soft++; px[i] = px[i] >= 128 ? 255 : 0; }
100	  for (let i = 0; i < px.length; i += 4) if (px[i + 3] === 0) px[i] = px[i + 1] = px[i + 2] = 0;
101	  if (soft) notes.push(`${soft} semi-transparent pixels made solid or clear (the studio paints opaque pixels)`);
102	  return { raster: { size, px }, notes };
103	}
