/** POST .../projects/:projectId/textures/:key/revisions { doc, baseAssetId, expectedHeadId, decision? }: save as a NEW revision. */
export const handleSaveRevision = (req: Request, p: P, deps: StudioApiDeps) => run(deps, { key: "save", max: 30 }, async ({ viewer }) => {
  const { projectId, key } = params(p, "projectId", "key");
  const b = await readJson(req);
  need(b.baseAssetId === null || (typeof b.baseAssetId === "string" && RE.id.test(b.baseAssetId)), "baseAssetId must be an asset id or null");
  need(b.expectedHeadId === null || (typeof b.expectedHeadId === "string" && RE.id.test(b.expectedHeadId)), "expectedHeadId must be a revision id or null");
  let decision = null;
  let also: string[] = [];
  if (b.acceptCandidate !== undefined) {
    // accepting: the server re-reads the candidate (never trusts a client copy of it) and records the decision
    need(typeof b.acceptCandidate === "string" && RE.id.test(b.acceptCandidate), "acceptCandidate must be a candidate id");
    const { project, chain, texture } = await textureForEdit(deps.service, viewer.userId, projectId, key);
    const sha = await candidateSpecSha(deps.candidates, { userId: viewer.userId, project, chain, texture, key, requestId: b.acceptCandidate as string });
    if (!sha) throw new StudioError(409, "candidate_not_ready", "That candidate isn't ready.");
    decision = { candidate: b.acceptCandidate as string, accepted: true };
    also = [sha];
  }
  const r = await saveTexture(deps.service, {
    userId: viewer.userId, projectId, key, doc: b.doc, baseAssetId: (b.baseAssetId as string | null) ?? null, expectedHeadId: (b.expectedHeadId as string | null) ?? null,
    decision, alsoSupersedes: also,
  });
  return json(201, r);
});

