function raster(size: number, f: (x: number, y: number) => [number, number, number, number]): Raster {
  const px = new Uint8ClampedArray(size * size * 4);
  for (let y = 0; y < size; y++) for (let x = 0; x < size; x++) px.set(f(x, y), (y * size + x) * 4);
  return { size, px };
}
